import{_ as t,o as e,c as r,a2 as n}from"./chunks/framework.DfDAiEgj.js";const o="/2bPM/img/private_computing_KG.png",b=JSON.parse('{"title":"怼 蓝象智联","description":"","frontmatter":{},"headers":[],"relativePath":"ai-company/trustbe.md","filePath":"ai-company/trustbe.md","lastUpdated":null}'),p={name:"ai-company/trustbe.md"};function l(i,a,h,s,c,m){return e(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="怼-蓝象智联" tabindex="-1">怼 蓝象智联 <a class="header-anchor" href="#怼-蓝象智联" aria-label="Permalink to &quot;怼 蓝象智联&quot;">​</a></h1><h2 id="人才" tabindex="-1">人才 <a class="header-anchor" href="#人才" aria-label="Permalink to &quot;人才&quot;">​</a></h2><p><a href="https://www.trustbe.cn/tdjs" target="_blank" rel="noreferrer">https://www.trustbe.cn/tdjs</a></p><p>JD照抄阿里的！！！</p><ul><li>阿里云智能事业群-产品经理-机器学习平台(JD):<a href="https://talent.alibaba.com/off-campus-position/637541?bucketType=A" target="_blank" rel="noreferrer">https://talent.alibaba.com/off-campus-position/637541?bucketType=A</a></li><li>蓝象科技:<a href="https://www.zhipin.com/job_detail/b35c1e9ba985fc101nV72tq5EFZZ.html" target="_blank" rel="noreferrer">https://www.zhipin.com/job_detail/b35c1e9ba985fc101nV72tq5EFZZ.html</a></li></ul><p><a href="https://www.tianyancha.com/company/3413932106" target="_blank" rel="noreferrer">https://www.tianyancha.com/company/3413932106</a></p><p>听说领英可以自己写公司，无必须公司认证</p><ul><li><a href="https://www.linkedin.com/in/%E4%BF%8A%E5%9B%BD-%E9%AB%98-498131106/" target="_blank" rel="noreferrer">https://www.linkedin.com/in/俊国-高-498131106/</a></li></ul><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>蓝象智联是一家金融级隐私计算服务商，公司定位于金融级隐私计算服务，公司核心产品已通过工信部和公安部认证，目前已被应用于多家银行、运营商和零售商业客户。同时，公司也在参与工信部等行业多方安全计算标准的制定。<a href="https://www.qcc.com/firm/efcbb8220d64ca34f4a85f5e1c0af260.html" target="_blank" rel="noreferrer">2</a></p><h2 id="隐私计算" tabindex="-1">隐私计算 <a class="header-anchor" href="#隐私计算" aria-label="Permalink to &quot;隐私计算&quot;">​</a></h2><p>背景：大数据时代下，数据所有权和使用权的矛盾已经十分激化，由于数据没有实体形态，拥有数据使用权的一方往往已经取得了数据的所有权。</p><p>同时，数据孤岛和极不通畅的数据沟通所带来的问题同样十分严重，而解决这类问题需要一种新的<strong>加密学</strong>的技术应用，这也就是后来发展出的隐私计算。<a href="https://www.cyzone.cn/article/615905.html" target="_blank" rel="noreferrer">5</a></p><p>随着个人信息保护法草案的亮相，如何在<strong>保护数据隐私的前提下解决数据孤岛问题</strong>，隐私计算被多个行业都视为颇具潜力的解决方式，特别是在金融行业。该行业是数据密集型行业，也是数据需求密集型行业，其风控、营销等能力都高度依赖于数据的支持——无论这些数据是来自金融机构内部还是外部。</p><p>“2B的赛道正在进入黄金发展期，其中数据相关赛道是2B众多赛道中最具有发展空间的，隐私计算是数据赛道的基础技术，我们非常看好隐私计算的前景，未来这个赛道的赢家一定是具备极强商业化落地能力，形成实质标准后将构筑<strong>极强的生态壁垒</strong>，而蓝象团队的综合实力无疑是业内比较领先的。”<a href="https://m.pedaily.cn/news/460985" target="_blank" rel="noreferrer">1</a></p><p>隐私计算能够让原始数据在不出库情况下实现数据价值交换，从根本上解决数据安全和数据交换价值的矛盾，结合区块链技术，通过分布式架构，不仅从技术层面解决数据“物理分散，逻辑集中”的问题，还能在生产关系层面解决中心化垄断问题，会使得各参与方更加积极的参与数据要素价值发现，这其中将有机会孕育新的业态 <a href="https://zhuanlan.zhihu.com/p/266323266" target="_blank" rel="noreferrer">7</a></p><p>蓝象智联CEO徐敏在“2020世界区块链大会”上表示，数据是金融的核心生产要素，是金融创新的原动力，安全是金融稳健创新的推动力。<strong>隐私计算</strong>与区块链助力金融实现“一切数据业务化”。隐私计算让数据“安全可用，不可见”。区块链是数据价值交换生态的底层基础设施。区块链和隐私计算是黄金搭档。</p><p>隐私计算虽然实现了在多方协作计算过程中的数据可用不可见，但是计算过程和结果缺乏均可验证性。而区块链因其共享账本、智能合约、共识机制等技术特性，可以实现数据的链上存证核验、计算过程关键数据和环节的上链存证回溯，确保计算过程的可验证性。因此将区块链技术对计算的可信证明应用到隐私计算中，可以辅助增强隐私计算任务中数据端到端及全生命周期的隐私性、安全性和可追溯性。《区块链辅助的隐私计算技术工具 技术要求与测试方法》标准聚焦于此，进一步完善了隐私计算的技术规范体系，希望助力行业的健康发展。<a href="https://www.databench.cn/index.php?m=content&amp;c=index&amp;a=show&amp;catid=10&amp;id=37" target="_blank" rel="noreferrer">6</a></p><p><img src="'+o+'" alt="隐私计算知识图谱4"></p><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p>作为金融级隐私计算产品，蓝象智联GAIA系列产品具有高安全、高精度、高性能、易用、高可用的特点。目前蓝象智联推出了两个产品系列，分别是数据安全计算节点GAIA EDGE以及一站式联邦学习平台GAIA CUBE。 <a href="https://www.jingpt.com/business/7edd2365-25c6-40a6-a876-0af65b29886e" target="_blank" rel="noreferrer">9</a></p><p>GAIA EDGE，是基于隐私计算构建数据彩虹桥，让不同机构之间的数据可以通过它实现数据价值流通和共享，既保护数据隐私、同时也消除数据孤岛，目前GAIA EDGE已经应用到多家金融机构和运营商。</p><p>GAIA CUBE，是一个蓝象智联推出的一站式联邦学习平台，把目前的模型人员在集中式建模过程的使用习惯在联邦学习和多方安全计算环境中得到保留。GAIA CUBE产品目前正在多家运营商和银行机构之间使用。</p><p>徐敏认为，云让“一切业务数据化”，隐私计算和区块链让“<strong>一切数据业务化</strong>”，隐私计算和区块链的结合是“一切数据业务化”的前提和必经途径。数据要素市场今天才刚刚开始，预估三年之内数据要素市场可以有10倍的增长，成为一个千亿级别的市场，蓝象智联将会配合数据方和数据使用方的客户和合作伙伴一起进步、一起进化，来让整个数据要素市场可以得到健康、合规的发展。</p><h3 id="产品体验与建议" tabindex="-1">产品体验与建议 <a class="header-anchor" href="#产品体验与建议" aria-label="Permalink to &quot;产品体验与建议&quot;">​</a></h3><p><a href="http://www.woshipm.com/ai/3123091.html" target="_blank" rel="noreferrer">http://www.woshipm.com/ai/3123091.html</a></p><p>[10]:</p>',27)])])}const d=t(p,[["render",l]]);export{b as __pageData,d as default};
